/**
 * The grouped list (row, section title, table footer), with no machine on `card`'s precedent: nothing here has
 * a state, an event or an id to derive, so `connect` takes the props directly.
 *
 * The group carries `role="list"`: WebKit drops the native role of a `ul` whose
 * style is `list-style: none`, so the role is written rather than left to the
 * element. The `li` keeps its native listitem semantics, and a row that acts does
 * so through its `action` part, which the consumer renders as the `a` or the
 * `button` that fits.
 */

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";

export type ListPart =
  | "root"
  | "section"
  | "header"
  | "group"
  | "row"
  | "action"
  | "leading"
  | "title"
  | "subtitle"
  | "trailing"
  | "footer";

export const anatomy: Anatomy<ListPart> = createAnatomy("list").parts(
  "root",
  "section",
  "header",
  "group",
  "row",
  "action",
  "leading",
  "title",
  "subtitle",
  "trailing",
  "footer",
);

export const parts: Record<ListPart, AnatomyPart> = anatomy.build();

/** `inset` is the rounded group, `plain` the same group edge to edge. */
export type ListVariant = "inset" | "plain";

/** `regular` is 52 on touch, `tall` 68 and makes room for a subtitle. */
export type ListRowSize = "regular" | "tall";

export interface ListMachineProps {
  /** Defaults to `"inset"`. */
  readonly variant?: ListVariant | undefined;
}

/** `auto` draws the chevron on a row that has an action, `none` withdraws it. */
export type ListRowChevron = "auto" | "none";

export interface ListRowOptions {
  /** Defaults to `"regular"`. */
  readonly size?: ListRowSize | undefined;
  /** Defaults to `"auto"`. */
  readonly chevron?: ListRowChevron | undefined;
}

export interface ListApi<T extends PropTypes = PropTypes> {
  readonly variant: ListVariant;
  getRootProps(): T["element"];
  getSectionProps(): T["element"];
  getHeaderProps(): T["element"];
  getGroupProps(): T["element"];
  getRowProps(options?: ListRowOptions): T["element"];
  getActionProps(): T["element"];
  getLeadingProps(): T["element"];
  getTitleProps(): T["element"];
  getSubtitleProps(): T["element"];
  getTrailingProps(): T["element"];
  getFooterProps(): T["element"];
}

export function connect<T extends PropTypes>(
  props: ListMachineProps,
  normalize: NormalizeProps<T>,
): ListApi<T> {
  const variant = props.variant ?? "inset";

  return {
    variant,
    getRootProps: (): T["element"] =>
      normalize.element({ ...parts.root.attrs, "data-variant": variant }),
    getSectionProps: (): T["element"] => normalize.element({ ...parts.section.attrs }),
    getHeaderProps: (): T["element"] => normalize.element({ ...parts.header.attrs }),
    getGroupProps: (): T["element"] => normalize.element({ ...parts.group.attrs, role: "list" }),
    getRowProps: (options: ListRowOptions = {}): T["element"] =>
      normalize.element({
        ...parts.row.attrs,
        "data-size": options.size ?? "regular",
        ...(options.chevron === "none" ? { "data-chevron": "none" } : {}),
      }),
    getActionProps: (): T["element"] => normalize.element({ ...parts.action.attrs }),
    getLeadingProps: (): T["element"] => normalize.element({ ...parts.leading.attrs }),
    getTitleProps: (): T["element"] => normalize.element({ ...parts.title.attrs }),
    getSubtitleProps: (): T["element"] => normalize.element({ ...parts.subtitle.attrs }),
    getTrailingProps: (): T["element"] => normalize.element({ ...parts.trailing.attrs }),
    getFooterProps: (): T["element"] => normalize.element({ ...parts.footer.attrs }),
  };
}

import type { ListMachineProps, ListRowOptions } from "@standarui/core/list";
import type { ReactNode } from "react";
import type { ComposedTrigger } from "../../composed";
import type { PartProps } from "../../create-part";
import {
  ListAction,
  ListFooter,
  ListGroup,
  ListHeader,
  ListLeading,
  ListRoot,
  ListRow,
  ListSection,
  ListSubtitle,
  ListTitle,
  ListTrailing,
} from "./list";

export interface ListParts {
  readonly section?: PartProps<"section"> | undefined;
  readonly header?: PartProps<"h3"> | undefined;
  readonly group?: PartProps<"ul"> | undefined;
  readonly footer?: PartProps<"p"> | undefined;
}

export interface ListComposedProps
  extends ListMachineProps,
    Omit<PartProps<"div", ListMachineProps>, "children"> {
  /** The section title, an `h3` over the group. */
  readonly header?: ReactNode;
  /** The rows of the group, most often `ListItem`s. */
  readonly children?: ReactNode;
  /** The note under the group. */
  readonly footer?: ReactNode;
  readonly parts?: ListParts | undefined;
}

export interface ListItemParts {
  readonly action?: PartProps<"button"> | undefined;
  readonly leading?: PartProps<"span"> | undefined;
  readonly title?: PartProps<"span"> | undefined;
  readonly subtitle?: PartProps<"span"> | undefined;
  readonly trailing?: PartProps<"span"> | undefined;
}

export interface ListItemComposedProps
  extends ListRowOptions,
    Omit<PartProps<"li", ListRowOptions>, "children" | "title"> {
  /** An image or an icon, flush with the row's start edge. */
  readonly leading?: ReactNode;
  /** The row's one line of text. */
  readonly title: Exclude<ReactNode, null | undefined | boolean>;
  /** The second line, for a `tall` row. */
  readonly subtitle?: ReactNode;
  /** The detail at the end. On an acting row the chevron follows it. */
  readonly trailing?: ReactNode;
  /**
   * The element the row's content is placed in, handed to the action part's
   * `render`: an `<a href>` or a `<button>`. Never placed as children.
   */
  readonly action?: ComposedTrigger | undefined;
  readonly parts?: ListItemParts | undefined;
}

const given = (slot: ReactNode): boolean => slot != null && slot !== false;

export function List(props: ListComposedProps): ReactNode {
  const { header, children, footer, parts, ...root } = props;

  return (
    <ListRoot {...root}>
      <ListSection {...parts?.section}>
        {given(header) ? <ListHeader {...parts?.header}>{header}</ListHeader> : null}
        {given(children) ? <ListGroup {...parts?.group}>{children}</ListGroup> : null}
        {given(footer) ? <ListFooter {...parts?.footer}>{footer}</ListFooter> : null}
      </ListSection>
    </ListRoot>
  );
}

export function ListItem(props: ListItemComposedProps): ReactNode {
  const { leading, title, subtitle, trailing, action, parts, ...row } = props;

  const content = (
    <>
      {given(leading) ? <ListLeading {...parts?.leading}>{leading}</ListLeading> : null}
      <ListTitle {...parts?.title}>{title}</ListTitle>
      {given(subtitle) ? <ListSubtitle {...parts?.subtitle}>{subtitle}</ListSubtitle> : null}
      {given(trailing) ? <ListTrailing {...parts?.trailing}>{trailing}</ListTrailing> : null}
    </>
  );

  return (
    <ListRow {...row}>
      {action === undefined ? (
        content
      ) : (
        <ListAction render={action} {...parts?.action}>
          {content}
        </ListAction>
      )}
    </ListRow>
  );
}

import * as list from "@standarui/core/list";
import { isValidElement, type ReactNode, useMemo, useRef } from "react";
import { composeRefs } from "../../compose-refs";
import type { PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { splitProps } from "../../split-props";
import { useInputModality } from "../../use-input-modality";
import { useRender } from "../../use-render";

export type ListApi = list.ListApi<ReactPropTypes>;

export function useList(props: list.ListMachineProps): ListApi {
  return list.connect(props, normalizeProps);
}

const api: ListApi = list.connect({}, normalizeProps);

const MACHINE_PROPS = ["variant"] as const;

export interface ListRootProps
  extends list.ListMachineProps,
    PartProps<"div", list.ListMachineProps> {}

export function ListRoot(props: ListRootProps): ReactNode {
  const [ownProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ref, ...elementProps } = rest;
  const node = useRef<HTMLElement | null>(null);
  const chained = useMemo(() => composeRefs<HTMLElement>(node, ref), [ref]);
  useInputModality(node);

  return useRender({
    render,
    asChild,
    element: "div",
    props: useList(ownProps).getRootProps(),
    elementProps: { ...elementProps, ref: chained },
    children,
  });
}

export function ListSection(props: PartProps<"section">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "section",
    props: api.getSectionProps(),
    elementProps,
    children,
  });
}

export function ListHeader(props: PartProps<"h3">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "h3",
    props: api.getHeaderProps(),
    elementProps,
    children,
  });
}

export function ListGroup(props: PartProps<"ul">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "ul",
    props: api.getGroupProps(),
    elementProps,
    children,
  });
}

export interface ListRowProps extends list.ListRowOptions, PartProps<"li", list.ListRowOptions> {}

export function ListRow(props: ListRowProps): ReactNode {
  const [ownProps, rest] = splitProps(props, ["size", "chevron"] as const);
  const { render, asChild, children, ...elementProps } = rest;

  return useRender({
    render,
    asChild,
    element: "li",
    props: api.getRowProps(ownProps),
    elementProps,
    children,
  });
}

function rendersButton(props: PartProps<"button">): boolean {
  if (props.asChild === true) return false;
  if (props.render === undefined) return true;
  return isValidElement(props.render) && props.render.type === "button";
}

export function ListAction(props: PartProps<"button">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "button",
    props: rendersButton(props)
      ? { type: "button", ...api.getActionProps() }
      : api.getActionProps(),
    elementProps,
    children,
  });
}

export function ListLeading(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getLeadingProps(),
    elementProps,
    children,
  });
}

export function ListTitle(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getTitleProps(),
    elementProps,
    children,
  });
}

export function ListSubtitle(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getSubtitleProps(),
    elementProps,
    children,
  });
}

export function ListTrailing(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getTrailingProps(),
    elementProps,
    children,
  });
}

export function ListFooter(props: PartProps<"p">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "p",
    props: api.getFooterProps(),
    elementProps,
    children,
  });
}
